/** CwhpManifestMapper.cwhpUpdateXrayInfo */
UPDATE
    XRAY_INFO
  SET
    CT_MRN = #{PIECES}
    ,WT_MRN = #{GWT}
    ,CTUNIT = #{UNIT_PIECES}
    ,VOYAGENO = #{VOYAGE}
    ,SHIPNAME = #{VESSEL_FLIGHT}
