    ,BL = #{HBL_NO}
    ,MBL = #{MBL_NO}
    ,CON = #{CON}
    ,SH_FIRM = #{SHIPPER_NAME}
    ,SH_NAD1 = SUBSTRING(ISNULL(CAST(UPPER(#{SHIPPER_ADDRESS}) AS NVARCHAR(300)), ''), 1, 50)
    ,SH_NAD2 = SUBSTRING(ISNULL(CAST(UPPER(#{SHIPPER_ADDRESS}) AS NVARCHAR(300)), ''), 50, 50)
    ,SH_NAD3 = SUBSTRING(ISNULL(CAST(UPPER(#{SHIPPER_ADDRESS}) AS NVARCHAR(300)), ''), 100, 50)
    ,SH_TEL = #{SHIPPER_TEL}
