    ,CN_NAD2 = SUBSTRING(ISNULL(CAST(UPPER(#{CONSIGNEE_ADDRESS}) AS NVARCHAR(300)), ''), 50, 50)
    ,CN_NAD3 = SUBSTRING(ISNULL(CAST(UPPER(#{CONSIGNEE_ADDRESS}) AS NVARCHAR(300)), ''), 100, 50)
    ,CN_TEL = #{CONSIGNEE_TEL}
    ,CUSTOMS_NUM = #{CUSTOMS_NUM} 
    ,GOODS_SELECT = #{ECM_TYPE}
    ,USE_SELECT = #{CD_USE_TYPE}
    ,SENDING_COUNTRY = #{SHIPPER_COUNTRY_CODE}
    ,LEVY = #{AMOUNT_CUR}
    ,INPUT_DATE = GETDATE()
    ,TRUCKER = #{TRUCKER}
    ,PASS_NOTI = #{INSPECTION_TYPE}
    ,ORI_PASS_NOTI = #{CD_TYPE}
    ,ORI_PASS_REASON = #{SE_INSPECTION_CODE}

    ,ADD_ISSUE_NOTE = #{REMARK}
    ,PID = #{PID}

WHERE
    MRN = #{MRN}
    AND MSN = #{MSN}
    AND HSN = #{HSN}

IF @@ROWCOUNT = 0

